    /**
     * Tests getting all Dependents.
     *
     * @return    Collection
     */
    public List<Dependent> testGetAll() throws Throwable {
    LOGGER.info( "DependentTest:testGetAll() - Retrieving Collection of Dependents:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Dependent : " );
    List<Dependent> collection  = null;

    try {
        // call the static get method on the DependentService
        collection = service.getAllDependent();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Dependent currEntity  = null;
            Iterator<Dependent> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getDependentId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

